110	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
111	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
112	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
113	        headers.setLocation(UriComponentsBuilder.newInstance()
114	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
115	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
121	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
122	        if (currentOwner == null) {
123	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
124	        }
125	        currentOwner.setAddress(ownerFieldsDto.getAddress());
126	        currentOwner.setCity(ownerFieldsDto.getCity());
127	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
128	        currentOwner.setLastName(ownerFieldsDto.getLastName());
129	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
130	        this.clinicService.saveOwner(currentOwner);
131	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Transactional
136	    @Override
137	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
138	        Owner owner = this.clinicService.findOwnerById(ownerId);
139	        if (owner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        this.clinicService.deleteOwner(owner);
143	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        HttpHeaders headers = new HttpHeaders();
154	        Pet pet = petMapper.toPet(petFieldsDto);
155	        owner.setId(ownerId);
156	        pet.setOwner(owner);
157	        pet.getType().setName(null);
158	        this.clinicService.savePet(pet);
159	        PetDto petDto = petMapper.toPetDto(pet);
160	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
161	            .buildAndExpand(pet.getId()).toUri());
162	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
168	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
169	        if (currentOwner != null) {
170	            Pet currentPet = this.clinicService.findPetById(petId);
171	            if (currentPet != null) {
172	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
173	                currentPet.setName(petFieldsDto.getName());
174	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
175	                this.clinicService.savePet(currentPet);
176	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
177	            }
178	        }
179	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
185	        HttpHeaders headers = new HttpHeaders();
186	        Visit visit = visitMapper.toVisit(visitFieldsDto);
187	        Pet pet = new Pet();
188	        pet.setId(petId);
189	        visit.setPet(pet);
190	        this.clinicService.saveVisit(visit);
191	        VisitDto visitDto = visitMapper.toVisitDto(visit);
192	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
193	            .buildAndExpand(visit.getId()).toUri());
194	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
195	    }
