16	package org.springframework.samples.petclinic.rest.advice;
17	
18	import org.aspectj.lang.annotation.AfterReturning;
19	import org.aspectj.lang.annotation.Aspect;
20	import org.springframework.http.ResponseEntity;
21	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Populates the read-only {@code membershipNumber} on an owner response, formatted
26	 * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the registration date year
27	 * (e.g. {@code 'SMI-0007-M26'}). Derived on the way out from the owner's own fields, so it never
28	 * affects storage or the request.
29	 */
30	@Aspect
31	@Component
32	public class OwnerMembershipNumberAdvice {
33	
34	    @AfterReturning(pointcut = "execution(* org.springframework.samples.petclinic.rest.controller.v1."
35	        + "OwnerRestControllerV1.addOwner(..)) || execution(* org.springframework.samples.petclinic.rest."
36	        + "controller.v1.OwnerRestControllerV1.getOwner(..))", returning = "response")
37	    public void addMembershipNumber(ResponseEntity<?> response) {
38	        Object body = response == null ? null : response.getBody();
39	        if (!(body instanceof OwnerDto owner) || owner.getCustomerCode() == null
40	            || owner.getRegistrationDate() == null) {
41	            return;
42	        }
43	        owner.setMembershipNumber(String.format("%s-M%02d",
44	            owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100));
45	    }
46	}
